FILE: app/src/timeline-loop.ts
```ts
import {
  createPropertyAnimationClip,
  createPropertyAnimationGroup,
  addAnimationGroup,
  playAnimation,
} from "@babylonjs/lite";
import type { AnimationManager, AnimationGroup } from "@babylonjs/lite";

export function loopKeyedTrack(
  manager: AnimationManager,
  target: object,
  path: string,
  keys: readonly { frame: number; value: number }[],
  frameRate: number
): AnimationGroup {
  const keyframes = keys.map((k) => ({ frame: k.frame, value: k.value }));

  const track = {
    path,
    keys: keyframes,
    interpolation: "linear" as const,
  };

  const clip = createPropertyAnimationClip(path, [track], { frameRate });

  const group = createPropertyAnimationGroup(manager, target, clip, {
    loop: true,
  });

  addAnimationGroup(manager, group);
  playAnimation(group);

  return group;
}
```

I wrote `src/timeline-loop.ts` which converts the raw frame/value keys into `AnimationKeyframe` objects, builds a single-track property animation clip with linear interpolation and the given frame rate, creates a looping animation group from it, registers the group with the manager, and starts playback. I was not 100% sure whether `createPropertyAnimationGroup` already adds the group to the manager's task list or whether `addAnimationGroup` is still needed; I included the explicit call to be safe (it should be harmless if the group is already registered).
